"""Статья «Современные системы вентиляции» и раздел «Тяга и опрокидывание» для страницы «Справочники → Вентиляция».

Исходный текст подготовлен ТЕГА ПЛЮС, здесь он проверен, исправлен и приведён к стилю сайта. Рекламный блок убран.
Что исправлено относительно исходника:
 - диаметры каналов и расходы при 2–3 м/с пересчитаны (круглые верны), эквивалентные прямоугольные сечения были неверны и пересчитаны по формуле;
 - требование рекуперации ≥ 73 % из Регламента ЕС 1253/2014 относится к нежилым двунаправленным установкам (для гликолевого контура 68 %), для жилых действует класс энергоэффективности SEC;
 - рыночные цифры (9,65 млрд $, ~50 %, +7,4 %) убраны: их источником были платные обзоры, проверить их нельзя;
 - «разрежение 5–10 %» дополнено оговоркой про открытые топки и атмосферные приборы;
 - исследование Harvard COGfx приведено с оговоркой: связь CO₂ и когнитивных функций оспаривается, CO₂ служит индикатором, а не единственной причиной;
 - рекуперация «до 92 %» из паспорта заменена честным диапазоном работы;
 - опечатки («никот нет»), противоречие в блоке «четыре нельзя» исправлены.
Новое: раздел про опрокидывание тяги, причины, проверка, типовые проблемы квартир и домов.
Нормы: СН 4.02.03-2019, (значения справочные); EN 308, ISO 16890, Regulation (EU) No 1253/2014.
"""
import math

from art_heat import _sec, _ul, _tbl, _note, _box, _p, _errs, _kpis
from art_vent_figs import (f_steps, f_co2, f_heatloss, f_apartment, f_cottage, f_draft, f_backdraft, f_leak, f_pyramid_v,
                           stack_pa, depress_pa, dew_point, ru)


def _de(a, b):
    return 1.3 * (a * b) ** 0.625 / (a + b) ** 0.25


def _rect(d, b):
    lo, hi = b, 5000.0
    for _ in range(60):
        mid = (lo + hi) / 2
        if _de(mid, b) < d:
            lo = mid
        else:
            hi = mid
    return int(math.ceil(hi / 10.0) * 10)


def _duct_rows():
    out = []
    for d, b in ((100, 60), (125, 80), (160, 100), (200, 100), (250, 150), (315, 200)):
        a = math.pi * (d / 1000.0) ** 2 / 4
        q2, q3 = a * 2 * 3600, a * 3 * 3600
        use = {100: "отвод к диффузору, бризер", 125: "ветка комнаты, санузел", 160: "ветка гостиной, кухонная вытяжка", 200: "магистраль квартиры, этажа",
               250: "магистраль коттеджа 150–250 м²", 315: "офис, венткамера, стояк"}[d]
        out.append([f"Ø{d} мм", f"{_rect(d, b)} × {b} мм", f"{round(q2, -1):.0f}–{round(q3, -1):.0f}", use])
    return out


